// Normalisation : minuscules, sans accents, apostrophes et ponctuation en espaces.
export function norm(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[’'`´]/g, ' ').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

// Petit stemmer français : pluriels et quelques terminaisons.
function stem(w) {
  if (w.length <= 3) return w;
  return w.replace(/(eaux)$/, 'eau').replace(/(aux)$/, 'al').replace(/(ies|ees|es|s|x)$/, '').replace(/(er|ir|re)$/, '');
}

// Index : expressions (avec espace) et mots simples (dédoublonnés par racine, poids max).
const INDEX = THEMES.map(t => {
  const phrases = [], byStem = new Map();
  const re = /([^:]+?):(\d)(?=\s|$)/g; let m;
  while ((m = re.exec(t.kw))) {
    const k = norm(m[1]), w = Number(m[2]);
    if (!k) continue;
    if (k.includes(' ')) { phrases.push([k, w * 2]); continue; }
    const st = stem(k);
    const cur = byStem.get(st);
    if (!cur || cur[1] < w) byStem.set(st, [k, w, st]);
  }
  return { id: t.id, icon: t.icon, phrases, words: [...byStem.values()] };
});

